/**
 * Everything around the athletes: the 105 x 68 m pitch, goals, stands with a
 * living crowd, floodlights, LED boards, sky and lighting. Generated by code,
 * except the covered stand, instanced from `public/assets/stadium/stand.glb`
 * (extracted from the owner's `football-court` model). Render-only.
 */
import type * as ThreeTypes from 'three';
import { seededRandom } from '../choreography';
import { FIELD } from '../projection';
import type { QualitySettings } from './quality';

type Three = typeof ThreeTypes;

export type Ambience = 'night' | 'dusk' | 'day';

interface AmbiencePreset {
  readonly skyTop: string;
  readonly skyHorizon: string;
  readonly fog: string;
  readonly hemiSky: string;
  readonly hemiGround: string;
  readonly hemi: number;
  readonly key: string;
  readonly keyIntensity: number;
  readonly fill: number;
  readonly lamps: number;
  readonly exposure: number;
  readonly stars: boolean;
  readonly keyFrom: readonly [number, number, number];
}

export const AMBIENCE: Readonly<Record<Ambience, AmbiencePreset>> = {
  night: {
    skyTop: '#04060d',
    skyHorizon: '#172443',
    fog: '#0a0f1d',
    hemiSky: '#a9bcff',
    hemiGround: '#1c3a24',
    hemi: 0.62,
    key: '#f6f8ff',
    keyIntensity: 2.5,
    fill: 0.62,
    lamps: 1,
    exposure: 1.08,
    stars: true,
    keyFrom: [40, 72, 48],
  },
  dusk: {
    skyTop: '#1a2152',
    skyHorizon: '#f08a5a',
    fog: '#3b3352',
    hemiSky: '#c5b6ff',
    hemiGround: '#28442a',
    hemi: 0.78,
    key: '#ffd8b0',
    keyIntensity: 2.3,
    fill: 0.5,
    lamps: 0.85,
    exposure: 1.02,
    stars: false,
    keyFrom: [70, 44, 40],
  },
  day: {
    skyTop: '#2b78d0',
    skyHorizon: '#c4e6ff',
    fog: '#bfe0f5',
    hemiSky: '#dcecff',
    hemiGround: '#3f6a3a',
    hemi: 1.15,
    key: '#fff4dc',
    keyIntensity: 3.1,
    fill: 0.3,
    lamps: 0,
    exposure: 0.98,
    stars: false,
    keyFrom: [46, 96, 30],
  },
};

/** Night games most of the time, with the odd sunset or afternoon kickoff. */
export function ambienceFor(seed: number): Ambience {
  const roll = (seed >>> 4) % 10;
  return roll < 5 ? 'night' : roll < 8 ? 'dusk' : 'day';
}

export interface EnvironmentOptions {
  readonly scene: ThreeTypes.Scene;
  readonly quality: QualitySettings;
  readonly ambience: Ambience;
  readonly seed: number;
  readonly anisotropy: number;
  readonly homeColour: string;
  readonly homeTrim: string;
  readonly awayColour: string;
  readonly homeName: string;
  /** The stand model; without it the stadium is drawn with plain terraces. */
  readonly stand: ThreeTypes.Object3D | null;
}

export interface Environment {
  readonly exposure: number;
  /** Per-frame update: crowd, boards, net, which stands are in the way. */
  update(
    time: number,
    dt: number,
    excitement: number,
    camera: ThreeTypes.Vector3,
  ): void;
  /** The ball hit the net on this side (home attacks +X). */
  shakeNet(side: 'home' | 'away'): void;
  setQuality(quality: QualitySettings): void;
  dispose(): void;
}

const HALF_L = FIELD.lineLength / 2;
const HALF_W = FIELD.lineWidth / 2;
const TURF_L = FIELD.lineLength + FIELD.margin * 2;
const TURF_W = FIELD.lineWidth + FIELD.margin * 2;

function paintPitch(width: number, seed: number): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  const scale = width / TURF_L;
  canvas.width = width;
  canvas.height = Math.round(TURF_W * scale);
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  const random = seededRandom(seed);
  const px = (metres: number) => metres * scale;
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;

  context.fillStyle = '#2c8339';
  context.fillRect(0, 0, canvas.width, canvas.height);
  // Mowing stripes across the length, a fainter pass across the width.
  const stripes = 18;
  const stripe = px(FIELD.lineLength / stripes);
  for (let index = -2; index < stripes + 2; index += 1) {
    context.fillStyle = index % 2 === 0 ? '#2f8a3b' : '#2a7d36';
    context.fillRect(
      px(FIELD.margin) + index * stripe,
      0,
      stripe + 1,
      canvas.height,
    );
  }
  const bands = 12;
  const band = px(FIELD.lineWidth / bands);
  for (let index = -2; index < bands + 2; index += 1) {
    context.fillStyle =
      index % 2 === 0 ? 'rgba(255,255,255,0.025)' : 'rgba(0,0,0,0.03)';
    context.fillRect(
      0,
      px(FIELD.margin) + index * band,
      canvas.width,
      band + 1,
    );
  }
  // Grain: thousands of tiny blades, lighter and darker.
  const blades = Math.round((canvas.width * canvas.height) / 55);
  for (let index = 0; index < blades; index += 1) {
    context.fillStyle =
      random() < 0.5 ? 'rgba(255,255,220,0.06)' : 'rgba(0,30,0,0.08)';
    context.fillRect(
      random() * canvas.width,
      random() * canvas.height,
      1 + random() * 1.6,
      1 + random() * 2.2,
    );
  }
  // Worn turf where the game is played hardest.
  const wear = (x: number, y: number, radius: number, alpha: number) => {
    const gradient = context.createRadialGradient(x, y, 0, x, y, radius);
    gradient.addColorStop(0, `rgba(122,104,58,${alpha})`);
    gradient.addColorStop(1, 'rgba(122,104,58,0)');
    context.fillStyle = gradient;
    context.fillRect(x - radius, y - radius, radius * 2, radius * 2);
  };
  wear(cx - px(HALF_L - 4), cy, px(9), 0.22);
  wear(cx + px(HALF_L - 4), cy, px(9), 0.22);
  wear(cx, cy, px(11), 0.1);
  // Darker run-off beyond the lines.
  context.fillStyle = 'rgba(0,0,0,0.16)';
  context.fillRect(0, 0, canvas.width, px(FIELD.margin) - px(0.3));
  context.fillRect(
    0,
    canvas.height - px(FIELD.margin) + px(0.3),
    canvas.width,
    px(FIELD.margin),
  );
  context.fillRect(0, 0, px(FIELD.margin) - px(0.3), canvas.height);
  context.fillRect(
    canvas.width - px(FIELD.margin) + px(0.3),
    0,
    px(FIELD.margin),
    canvas.height,
  );

  // Markings.
  context.strokeStyle = 'rgba(255,255,255,0.93)';
  context.fillStyle = 'rgba(255,255,255,0.93)';
  context.lineWidth = Math.max(2, px(0.14));
  const left = cx - px(HALF_L);
  const right = cx + px(HALF_L);
  const top = cy - px(HALF_W);
  const bottom = cy + px(HALF_W);
  context.strokeRect(left, top, right - left, bottom - top);
  context.beginPath();
  context.moveTo(cx, top);
  context.lineTo(cx, bottom);
  context.stroke();
  context.beginPath();
  context.arc(cx, cy, px(9.15), 0, Math.PI * 2);
  context.stroke();
  const spot = (x: number, y: number) => {
    context.beginPath();
    context.arc(x, y, px(0.22), 0, Math.PI * 2);
    context.fill();
  };
  spot(cx, cy);
  for (const direction of [-1, 1] as const) {
    const line = cx + direction * px(HALF_L);
    const box = (depth: number, half: number) =>
      context.strokeRect(
        direction === 1 ? line - px(depth) : line,
        cy - px(half),
        px(depth),
        px(half * 2),
      );
    box(16.5, 20.16);
    box(5.5, 9.16);
    const penalty = line - direction * px(11);
    spot(penalty, cy);
    // The "D": the part of the 9.15 m circle outside the box.
    const reach = Math.acos(5.5 / 9.15);
    context.beginPath();
    if (direction === 1)
      context.arc(penalty, cy, px(9.15), Math.PI - reach, Math.PI + reach);
    else context.arc(penalty, cy, px(9.15), -reach, reach);
    context.stroke();
    for (const edge of [top, bottom]) {
      context.beginPath();
      const start =
        direction === 1
          ? edge === top
            ? Math.PI / 2
            : Math.PI
          : edge === top
            ? 0
            : -Math.PI / 2;
      context.arc(line, edge, px(1), start, start + Math.PI / 2);
      context.stroke();
    }
  }
  return canvas;
}

function paintNet(): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 64;
  canvas.height = 64;
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  context.strokeStyle = 'rgba(255,255,255,0.9)';
  context.lineWidth = 3;
  context.strokeRect(0, 0, 64, 64);
  return canvas;
}

function paintGlow(inner: string): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  const gradient = context.createRadialGradient(64, 64, 0, 64, 64, 64);
  gradient.addColorStop(0, inner);
  gradient.addColorStop(0.25, 'rgba(255,255,255,0.35)');
  gradient.addColorStop(1, 'rgba(255,255,255,0)');
  context.fillStyle = gradient;
  context.fillRect(0, 0, 128, 128);
  return canvas;
}

function paintLamps(): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  context.fillStyle = '#0c0e12';
  context.fillRect(0, 0, 256, 128);
  for (let row = 0; row < 4; row += 1)
    for (let column = 0; column < 8; column += 1) {
      const x = 16 + column * 32;
      const y = 16 + row * 32;
      const gradient = context.createRadialGradient(x, y, 1, x, y, 13);
      gradient.addColorStop(0, '#ffffff');
      gradient.addColorStop(0.6, '#fff6d8');
      gradient.addColorStop(1, 'rgba(255,240,200,0)');
      context.fillStyle = gradient;
      context.fillRect(x - 14, y - 14, 28, 28);
    }
  return canvas;
}

function paintBoards(texts: readonly string[]): HTMLCanvasElement {
  const canvas = document.createElement('canvas');
  canvas.width = 4096;
  canvas.height = 64;
  const context = canvas.getContext('2d');
  if (!context) return canvas;
  const palettes = [
    ['#0b3d1f', '#e7ff54'],
    ['#101827', '#ffffff'],
    ['#7a0c14', '#ffffff'],
    ['#e7b416', '#14181d'],
    ['#0d2b5c', '#8fd3ff'],
    ['#f4f4f0', '#14181d'],
  ] as const;
  const panel = canvas.width / 8;
  context.textAlign = 'center';
  context.textBaseline = 'middle';
  context.font = '800 38px "Arial Narrow", "Helvetica Neue", Arial, sans-serif';
  for (let index = 0; index < 8; index += 1) {
    const [background, ink] = palettes[index % palettes.length]!;
    context.fillStyle = background;
    context.fillRect(index * panel, 0, panel, 64);
    context.fillStyle = ink;
    context.fillText(
      texts[index % texts.length]!,
      index * panel + panel / 2,
      34,
      panel - 40,
    );
  }
  return canvas;
}

interface StandSide {
  readonly name: 'north' | 'south' | 'east' | 'west';
  readonly origin: readonly [number, number];
  readonly rotation: number;
  /** Stretch along the stand so two copies cover the side. */
  readonly length: number;
  readonly offsets: readonly number[];
}

/** Model units to metres: the stand becomes 55 m long and 26 m tall. */
const STAND_UNIT = 2.5;
const STAND_GAP = 2.6;

const STAND_SIDES: readonly StandSide[] = [
  {
    name: 'north',
    origin: [0, -(HALF_W + FIELD.margin + STAND_GAP)],
    rotation: 0,
    length: 1,
    offsets: [-27.5, 27.5],
  },
  {
    name: 'south',
    origin: [0, HALF_W + FIELD.margin + STAND_GAP],
    rotation: Math.PI,
    length: 1,
    offsets: [-27.5, 27.5],
  },
  {
    name: 'east',
    origin: [HALF_L + FIELD.margin + STAND_GAP + 1, 0],
    rotation: -Math.PI / 2,
    length: 0.7,
    offsets: [-19.25, 19.25],
  },
  {
    name: 'west',
    origin: [-(HALF_L + FIELD.margin + STAND_GAP + 1), 0],
    rotation: Math.PI / 2,
    length: 0.7,
    offsets: [-19.25, 19.25],
  },
];

export function createEnvironment(
  THREE: Three,
  options: EnvironmentOptions,
): Environment {
  const { scene, ambience } = options;
  const preset = AMBIENCE[ambience];
  const random = seededRandom(options.seed ^ 0x5f3759df);
  const disposables: Array<{ dispose(): void }> = [];
  const track = <T extends { dispose(): void }>(item: T): T => {
    disposables.push(item);
    return item;
  };
  const added: ThreeTypes.Object3D[] = [];
  const add = <T extends ThreeTypes.Object3D>(object: T): T => {
    scene.add(object);
    added.push(object);
    return object;
  };
  const canvasTexture = (canvas: HTMLCanvasElement) => {
    const texture = track(new THREE.CanvasTexture(canvas));
    texture.colorSpace = THREE.SRGBColorSpace;
    texture.anisotropy = options.anisotropy;
    return texture;
  };
  let quality = options.quality;

  // --- Sky, fog and light. --------------------------------------------------
  scene.fog = new THREE.Fog(preset.fog, 190, 620);
  scene.background = new THREE.Color(preset.fog);
  const skyMaterial = track(
    new THREE.ShaderMaterial({
      side: THREE.BackSide,
      depthWrite: false,
      fog: false,
      uniforms: {
        top: { value: new THREE.Color(preset.skyTop) },
        horizon: { value: new THREE.Color(preset.skyHorizon) },
      },
      vertexShader:
        'varying vec3 vDirection; void main(){ vDirection = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }',
      fragmentShader:
        'uniform vec3 top; uniform vec3 horizon; varying vec3 vDirection; void main(){ float h = pow(clamp(vDirection.y, 0.0, 1.0), 0.55); gl_FragColor = vec4(mix(horizon, top, h), 1.0); }',
    }),
  );
  add(
    new THREE.Mesh(track(new THREE.SphereGeometry(900, 24, 12)), skyMaterial),
  );
  if (preset.stars) {
    const count = 700;
    const positions = new Float32Array(count * 3);
    for (let index = 0; index < count; index += 1) {
      const azimuth = random() * Math.PI * 2;
      const elevation = 0.12 + random() * 1.4;
      positions[index * 3] = Math.cos(azimuth) * Math.cos(elevation) * 850;
      positions[index * 3 + 1] = Math.sin(elevation) * 850;
      positions[index * 3 + 2] = Math.sin(azimuth) * Math.cos(elevation) * 850;
    }
    const geometry = track(new THREE.BufferGeometry());
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    add(
      new THREE.Points(
        geometry,
        track(
          new THREE.PointsMaterial({
            color: '#dfe8ff',
            size: 1.6,
            sizeAttenuation: false,
            fog: false,
            transparent: true,
            opacity: 0.8,
          }),
        ),
      ),
    );
  }

  add(
    new THREE.HemisphereLight(preset.hemiSky, preset.hemiGround, preset.hemi),
  );
  const key = add(new THREE.DirectionalLight(preset.key, preset.keyIntensity));
  key.position.set(...preset.keyFrom);
  key.shadow.camera.left = -64;
  key.shadow.camera.right = 64;
  key.shadow.camera.top = 44;
  key.shadow.camera.bottom = -44;
  key.shadow.camera.near = 10;
  key.shadow.camera.far = 240;
  key.shadow.bias = -0.0005;
  key.shadow.normalBias = 0.05;
  const applyShadows = () => {
    key.castShadow = quality.shadows;
    if (quality.shadows && key.shadow.mapSize.x !== quality.shadowMap) {
      key.shadow.mapSize.set(quality.shadowMap, quality.shadowMap);
      key.shadow.map?.dispose();
      key.shadow.map = null;
    }
  };
  applyShadows();
  // The other three towers: light without shadows.
  for (const [x, z] of [
    [-preset.keyFrom[0], preset.keyFrom[2]],
    [preset.keyFrom[0], -preset.keyFrom[2]],
    [-preset.keyFrom[0], -preset.keyFrom[2]],
  ] as const) {
    const fill = add(new THREE.DirectionalLight(preset.key, preset.fill));
    fill.position.set(x, preset.keyFrom[1], z);
  }

  // --- Ground and pitch. ----------------------------------------------------
  const ground = add(
    new THREE.Mesh(
      track(new THREE.PlaneGeometry(900, 900)),
      track(new THREE.MeshStandardMaterial({ color: '#12151a', roughness: 1 })),
    ),
  );
  ground.rotation.x = -Math.PI / 2;
  ground.position.y = -0.06;
  const apron = add(
    new THREE.Mesh(
      track(new THREE.PlaneGeometry(TURF_L + 14, TURF_W + 12)),
      track(
        new THREE.MeshStandardMaterial({ color: '#3a3d42', roughness: 0.95 }),
      ),
    ),
  );
  apron.rotation.x = -Math.PI / 2;
  apron.position.y = -0.03;
  apron.receiveShadow = true;

  const pitchTexture = canvasTexture(
    paintPitch(quality.pitchTexture, options.seed),
  );
  const pitch = add(
    new THREE.Mesh(
      track(new THREE.PlaneGeometry(TURF_L, TURF_W)),
      track(
        new THREE.MeshStandardMaterial({ map: pitchTexture, roughness: 0.94 }),
      ),
    ),
  );
  pitch.rotation.x = -Math.PI / 2;
  pitch.receiveShadow = true;

  // --- Goals. ----------------------------------------------------------------
  const postMaterial = track(
    new THREE.MeshStandardMaterial({ color: '#f7f7f4', roughness: 0.35 }),
  );
  const netTexture = canvasTexture(paintNet());
  netTexture.wrapS = THREE.RepeatWrapping;
  netTexture.wrapT = THREE.RepeatWrapping;
  const netMaterial = (repeatX: number, repeatY: number) => {
    const map = track(netTexture.clone());
    map.needsUpdate = true;
    map.repeat.set(repeatX * 6, repeatY * 6);
    return track(
      new THREE.MeshBasicMaterial({
        map,
        transparent: true,
        opacity: 0.55,
        side: THREE.DoubleSide,
        depthWrite: false,
      }),
    );
  };
  const postGeometry = track(
    new THREE.CylinderGeometry(0.065, 0.065, FIELD.goalHeight, 10),
  );
  const barGeometry = track(
    new THREE.CylinderGeometry(0.065, 0.065, FIELD.goalWidth + 0.13, 10),
  );
  const nets: Record<
    'home' | 'away',
    { mesh: ThreeTypes.Group; kick: number; velocity: number }
  > = {
    home: { mesh: new THREE.Group(), kick: 0, velocity: 0 },
    away: { mesh: new THREE.Group(), kick: 0, velocity: 0 },
  };
  for (const attacking of ['home', 'away'] as const) {
    const direction = attacking === 'home' ? 1 : -1;
    const goal = add(new THREE.Group());
    goal.position.x = direction * HALF_L;
    for (const z of [-FIELD.goalWidth / 2, FIELD.goalWidth / 2]) {
      const post = new THREE.Mesh(postGeometry, postMaterial);
      post.position.set(0, FIELD.goalHeight / 2, z);
      post.castShadow = true;
      goal.add(post);
    }
    const bar = new THREE.Mesh(barGeometry, postMaterial);
    bar.rotation.x = Math.PI / 2;
    bar.position.y = FIELD.goalHeight;
    bar.castShadow = true;
    goal.add(bar);
    const net = nets[attacking].mesh;
    const back = new THREE.Mesh(
      track(new THREE.PlaneGeometry(FIELD.goalWidth, FIELD.goalHeight)),
      netMaterial(FIELD.goalWidth, FIELD.goalHeight),
    );
    back.rotation.y = Math.PI / 2;
    back.position.set(direction * FIELD.goalDepth, FIELD.goalHeight / 2, 0);
    net.add(back);
    const roof = new THREE.Mesh(
      track(new THREE.PlaneGeometry(FIELD.goalDepth, FIELD.goalWidth)),
      netMaterial(FIELD.goalDepth, FIELD.goalWidth),
    );
    roof.rotation.x = -Math.PI / 2;
    roof.position.set((direction * FIELD.goalDepth) / 2, FIELD.goalHeight, 0);
    net.add(roof);
    for (const z of [-FIELD.goalWidth / 2, FIELD.goalWidth / 2]) {
      const side = new THREE.Mesh(
        track(new THREE.PlaneGeometry(FIELD.goalDepth, FIELD.goalHeight)),
        netMaterial(FIELD.goalDepth, FIELD.goalHeight),
      );
      side.position.set(
        (direction * FIELD.goalDepth) / 2,
        FIELD.goalHeight / 2,
        z,
      );
      net.add(side);
    }
    goal.add(net);
  }

  // Corner flags.
  const flagPole = track(new THREE.CylinderGeometry(0.025, 0.025, 1.5, 6));
  const flagCloth = track(new THREE.PlaneGeometry(0.42, 0.3));
  const flagMaterial = track(
    new THREE.MeshBasicMaterial({ color: '#f2c230', side: THREE.DoubleSide }),
  );
  for (const x of [-HALF_L, HALF_L])
    for (const z of [-HALF_W, HALF_W]) {
      const pole = add(new THREE.Mesh(flagPole, postMaterial));
      pole.position.set(x, 0.75, z);
      const cloth = add(new THREE.Mesh(flagCloth, flagMaterial));
      cloth.position.set(x + 0.21, 1.33, z);
    }

  // --- LED boards around the pitch. ------------------------------------------
  const boardTexture = canvasTexture(
    paintBoards([
      'FOOTEBAS',
      options.homeName.toUpperCase(),
      'RANKING GLOBAL',
      'MERCADO DA BOLA',
      'CLUBE ONLINE',
      'VÁRZEA FM',
    ]),
  );
  boardTexture.wrapS = THREE.RepeatWrapping;
  const boardMaterial = track(
    new THREE.MeshBasicMaterial({ map: boardTexture, toneMapped: false }),
  );
  boardMaterial.color.setScalar(0.5 + 0.75 * preset.lamps);
  const board = (length: number, x: number, z: number, rotation: number) => {
    const geometry = track(new THREE.BoxGeometry(length, 1, 0.25));
    const mesh = add(new THREE.Mesh(geometry, boardMaterial));
    mesh.position.set(x, 0.5, z);
    mesh.rotation.y = rotation;
  };
  board(FIELD.lineLength - 6, 0, -(HALF_W + FIELD.margin - 1.6), 0);
  board(TURF_W - 14, HALF_L + FIELD.margin - 1.2, 0, Math.PI / 2);
  board(TURF_W - 14, -(HALF_L + FIELD.margin - 1.2), 0, Math.PI / 2);

  // --- Stands and crowd. -------------------------------------------------------
  const standGroups = new Map<StandSide['name'], ThreeTypes.Group>();
  const crowdMeshes: ThreeTypes.InstancedMesh[] = [];
  const crowdTotals: number[] = [];
  const crowdUniforms = { uTime: { value: 0 }, uExcite: { value: 0 } };
  const animateCrowd = (material: ThreeTypes.Material) => {
    material.onBeforeCompile = (shader) => {
      shader.uniforms.uTime = crowdUniforms.uTime;
      shader.uniforms.uExcite = crowdUniforms.uExcite;
      shader.vertexShader = shader.vertexShader
        .replace(
          '#include <common>',
          '#include <common>\nattribute float aPhase;\nuniform float uTime;\nuniform float uExcite;',
        )
        .replace(
          '#include <begin_vertex>',
          `#include <begin_vertex>
          float wave = sin(uTime * (5.0 + aPhase * 3.0) + aPhase * 40.0);
          transformed.y += (abs(wave) * (0.06 + uExcite * 0.55 * (0.5 + aPhase)))
            + sin(uTime * 0.9 + aPhase * 17.0) * 0.02;`,
        );
    };
  };

  const pieces = new Map<string, ThreeTypes.BufferGeometry>();
  options.stand?.traverse((object) => {
    const mesh = object as ThreeTypes.Mesh;
    if (mesh.isMesh) pieces.set(mesh.name, track(mesh.geometry));
  });
  const terrace = pieces.size === 0;
  const standMaterials = {
    structure: track(
      new THREE.MeshStandardMaterial({ color: '#2a2f37', roughness: 0.9 }),
    ),
    seats: track(
      new THREE.MeshStandardMaterial({
        color: new THREE.Color(options.homeColour).lerp(
          new THREE.Color('#10141a'),
          0.74,
        ),
        roughness: 0.7,
      }),
    ),
    roof: track(
      new THREE.MeshStandardMaterial({
        color: '#171a20',
        roughness: 0.5,
        metalness: 0.4,
        side: THREE.DoubleSide,
      }),
    ),
  };
  if (terrace) {
    // No model: a plain raked terrace with the same footprint.
    const geometry = new THREE.BoxGeometry(22, 5.4, 10.8);
    geometry.translate(0, 2.7, -5.4);
    pieces.set('structure', track(geometry));
  }
  const bodyGeometry = track(new THREE.BoxGeometry(0.62, 0.78, 0.4));
  bodyGeometry.translate(0, 0.39, 0);
  const headGeometry = track(new THREE.IcosahedronGeometry(0.19, 0));
  headGeometry.translate(0, 1.0, 0);
  const bodyMaterial = track(new THREE.MeshLambertMaterial());
  const headMaterial = track(new THREE.MeshLambertMaterial());
  animateCrowd(bodyMaterial);
  animateCrowd(headMaterial);
  const fanSkin = ['#f1c9a5', '#dba77a', '#b9794d', '#8a5632', '#5f3a22'];
  const neutral = ['#e9e9e4', '#1c2026', '#59616c', '#a7adb5'];
  const matrix = new THREE.Matrix4();
  const standMatrix = new THREE.Matrix4();
  const scaleMatrix = new THREE.Matrix4();
  const seat = new THREE.Vector3();
  const colour = new THREE.Color();

  for (const side of STAND_SIDES) {
    const group = add(new THREE.Group());
    group.name = `stand-${side.name}`;
    standGroups.set(side.name, group);
    const placements = side.offsets.map((offset) => {
      const placed = new THREE.Matrix4()
        .makeRotationY(side.rotation)
        .setPosition(side.origin[0], 0, side.origin[1]);
      matrix.makeTranslation(offset, 0, 0);
      placed.multiply(matrix);
      scaleMatrix.makeScale(STAND_UNIT * side.length, STAND_UNIT, STAND_UNIT);
      return placed.multiply(scaleMatrix);
    });
    for (const [name, geometry] of pieces) {
      const material =
        standMaterials[name as keyof typeof standMaterials] ??
        standMaterials.structure;
      const mesh = new THREE.InstancedMesh(
        geometry,
        material,
        placements.length,
      );
      placements.forEach((placement, index) =>
        mesh.setMatrixAt(index, placement),
      );
      mesh.frustumCulled = false;
      group.add(mesh);
    }

    // One fan per seat: ten rows, three blocks split by two aisles.
    const seats: Array<{ x: number; y: number; z: number }> = [];
    for (const placement of placements) {
      standMatrix.copy(placement);
      for (let row = 0; row < 10; row += 1)
        for (let x = -9.85; x <= 9.85; x += 0.37 / side.length) {
          if (Math.abs(Math.abs(x) - 3.5) < 0.55) continue;
          if (random() > 0.94) continue;
          seat
            .set(
              x + (random() - 0.5) * 0.08,
              terrace ? 0.55 * row + 0.5 : 1.42 + 0.5 * row,
              terrace ? -0.5 - row : -0.33 - row,
            )
            .applyMatrix4(standMatrix);
          seats.push({ x: seat.x, y: seat.y, z: seat.z });
        }
    }
    // Shuffled, so thinning the crowd for weaker devices empties it evenly.
    for (let index = seats.length - 1; index > 0; index -= 1) {
      const other = Math.floor(random() * (index + 1));
      [seats[index], seats[other]] = [seats[other]!, seats[index]!];
    }
    const phases = new Float32Array(seats.length);
    const bodies = new THREE.InstancedMesh(
      bodyGeometry.clone(),
      bodyMaterial,
      seats.length,
    );
    const heads = new THREE.InstancedMesh(
      headGeometry.clone(),
      headMaterial,
      seats.length,
    );
    track(bodies.geometry);
    track(heads.geometry);
    // Visitors take a block behind the goal their team defends in the first half.
    const visitors = side.name === 'east';
    seats.forEach((position, index) => {
      matrix
        .makeRotationY(side.rotation)
        .setPosition(position.x, position.y, position.z);
      bodies.setMatrixAt(index, matrix);
      heads.setMatrixAt(index, matrix);
      phases[index] = random();
      const roll = random();
      const away = visitors && position.z > -4;
      colour.set(
        roll < 0.62
          ? away
            ? options.awayColour
            : options.homeColour
          : roll < 0.8 && !away
            ? options.homeTrim
            : neutral[Math.floor(random() * neutral.length)]!,
      );
      colour.offsetHSL(0, 0, (random() - 0.5) * 0.08);
      bodies.setColorAt(index, colour);
      heads.setColorAt(
        index,
        colour.set(fanSkin[Math.floor(random() * fanSkin.length)]!),
      );
    });
    for (const mesh of [bodies, heads]) {
      mesh.geometry.setAttribute(
        'aPhase',
        new THREE.InstancedBufferAttribute(phases, 1),
      );
      mesh.frustumCulled = false;
      group.add(mesh);
      crowdMeshes.push(mesh);
      crowdTotals.push(seats.length);
    }
  }
  const applyCrowd = () =>
    crowdMeshes.forEach((mesh, index) => {
      mesh.count = Math.round(crowdTotals[index]! * quality.crowd);
    });
  applyCrowd();

  // --- Floodlight towers. ------------------------------------------------------
  const lampTexture = canvasTexture(paintLamps());
  const lampMaterial = track(
    new THREE.MeshBasicMaterial({ map: lampTexture, toneMapped: false }),
  );
  lampMaterial.color.setScalar(0.25 + 2.4 * preset.lamps);
  const glowMaterial = track(
    new THREE.SpriteMaterial({
      map: canvasTexture(paintGlow('rgba(255,255,255,0.95)')),
      blending: THREE.AdditiveBlending,
      depthWrite: false,
      transparent: true,
      opacity: 0.85 * preset.lamps,
      fog: false,
    }),
  );
  const towerMaterial = track(
    new THREE.MeshStandardMaterial({
      color: '#3b414b',
      roughness: 0.6,
      metalness: 0.5,
    }),
  );
  const towerGeometry = track(new THREE.CylinderGeometry(0.7, 1.1, 44, 8));
  const headGeometryBox = track(new THREE.BoxGeometry(15, 8, 1));
  const lampGeometry = track(new THREE.PlaneGeometry(14, 7));
  for (const x of [-1, 1])
    for (const z of [-1, 1]) {
      const tower = add(new THREE.Group());
      tower.position.set(x * (HALF_L + 18), 0, z * (HALF_W + 22));
      const pole = new THREE.Mesh(towerGeometry, towerMaterial);
      pole.position.y = 22;
      tower.add(pole);
      const head = new THREE.Group();
      head.position.y = 46;
      head.add(new THREE.Mesh(headGeometryBox, towerMaterial));
      const lamps = new THREE.Mesh(lampGeometry, lampMaterial);
      lamps.position.z = 0.52;
      head.add(lamps);
      tower.add(head);
      head.lookAt(0, 4, 0);
      if (preset.lamps > 0) {
        const glow = new THREE.Sprite(glowMaterial);
        glow.scale.setScalar(46);
        glow.position.y = 46;
        tower.add(glow);
      }
    }

  return {
    exposure: preset.exposure,
    update(time, dt, excitement, camera) {
      crowdUniforms.uTime.value = time;
      crowdUniforms.uExcite.value = excitement;
      boardTexture.offset.x = (time * 0.012) % 1;
      // A stand between the camera and the pitch steps out of the picture.
      const low = camera.y < 38;
      standGroups.get('north')!.visible = !(low && camera.z < -38);
      standGroups.get('south')!.visible = !(low && camera.z > 38);
      standGroups.get('east')!.visible = !(low && camera.x > HALF_L + 6);
      standGroups.get('west')!.visible = !(low && camera.x < -(HALF_L + 6));
      // Damped spring: the net bulges when the ball arrives and settles.
      for (const net of Object.values(nets)) {
        if (net.kick === 0 && net.velocity === 0) continue;
        net.velocity += (-net.kick * 90 - net.velocity * 7) * dt;
        net.kick += net.velocity * dt;
        if (Math.abs(net.kick) < 0.001 && Math.abs(net.velocity) < 0.01) {
          net.kick = 0;
          net.velocity = 0;
        }
        net.mesh.scale.x = 1 + net.kick;
      }
    },
    shakeNet(side) {
      nets[side].velocity = 3.2;
    },
    setQuality(next) {
      quality = next;
      applyShadows();
      applyCrowd();
    },
    dispose() {
      added.forEach((object) => scene.remove(object));
      crowdMeshes.forEach((mesh) => mesh.dispose());
      disposables.forEach((item) => item.dispose());
      scene.fog = null;
    },
  };
}
